// generated by Google AI Assistent 13.08.2026
#define UUID_BLOCKSIZE 16
int32_t UsintToHex(const uint8_t* pIn, uint8_t* pHex)
{
	// lookup-table for hex chars
	static const char hexChars[] = "0123456789abcdef";
	uint16_t i = 0;
	
	for (i = 0; i < UUID_BLOCKSIZE; i++)
	{
		uint8_t byte = pIn[i];
		// high nibble
		pHex[2 * i]     = hexChars[byte >> 4];
		// low nibble
		pHex[2 * i + 1] = hexChars[byte & 0x0F];
	}
    
	// string termination
	pHex[2 * UUID_BLOCKSIZE] = '\0'; 
	return 0;
}

