// add uuid defined separators -> 36 chars + \0 is result!
void HexStrToUUID(const uint8_t* pHex, uint8_t* pUUID)
{
	uint32_t offsetDest = 0;
	uint32_t offsetSrc = 0;
	uint8_t i = 0;
	
	memcpy(pUUID + offsetDest, pHex + offsetSrc, 8);
	offsetDest += 8;
	offsetSrc += 8;
	memset(pUUID + offsetDest, '-', 1);
	offsetDest += 1;
	for (i = 0; i < 3; i++)
	{
		memcpy(pUUID + offsetDest, pHex + offsetSrc, 4);
		offsetDest += 4;
		offsetSrc += 4;
		memset(pUUID + offsetDest, '-', 1);
		offsetDest += 1;
	}
	memcpy(pUUID + offsetDest, pHex + offsetSrc, 12);
	offsetDest += 12;
	memset(pUUID + offsetDest, 0, 1);
}

// read the device date and time 
uint32_t GetDTSecs(void)
{
	DTGetTime_typ dt;
	dt.enable = 1;
	DTGetTime(&dt);
	if (dt.status == 0)
		return dt.DT1;
	else
		return 0;
}

// generate seed based on entropy data (fallback: based on rtc) & predefined prime numbers
uint32_t generate_seed(uint32_t number, uint32_t mix, uint32_t salt)
{
	return (number * mix) + salt;
}

